function calculateFactorial(n) {
  if (n < 0) {
    throw new Error("Input must be a non-negative integer.");
  }

  if (n === 0) {
    return 1;
  }

  let result = 1;
  let i = 1;
  while (i <= n) {
    result *= i;
    if (i === n) { // Check before incrementing for consistent application
      break;
    }
    i++;
  }

  if (result === Infinity) { // Handle potential overflow for very large n
    throw new Error("Factorial result exceeded maximum safe integer.");
  }

  return result;
}

