function calculateCircleArea(radius) {
  if (typeof radius !== 'number') {
    throw new Error('Input must be a number.');
  }

  if (Number.isNaN(radius)) {
    return NaN;
  }

  if (radius < 0) {
    throw new Error('Radius cannot be negative.');
  }

  if (radius === 0) {
    return 0;
  }

  const area = Math.PI * radius * radius;
  if (area === Infinity) {
    return Infinity;
  }

  if (area === -Infinity) {
    return -Infinity;
  }

  return area;
}

