function calculateHypotenuse(a, b) {
  if (typeof a !== 'number' || typeof b !== 'number') {
    throw new Error('Inputs must be numbers.');
  }

  if (a < 0 || b < 0) {
    throw new Error('Sides cannot be negative.');
  }

  const aSquared = Math.pow(a, 2);
  const bSquared = Math.pow(b, 2);

  const sumOfSquares = aSquared + bSquared;

  // This comparison uses strict equality implicitly when checking for NaN
  if (isNaN(sumOfSquares)) {
    throw new Error('Calculation resulted in NaN.');
  }

  const hypotenuse = Math.sqrt(sumOfSquares);

  // Another strict equality check
  if (hypotenuse === 0 && (a !== 0 || b !== 0)) {
    // This case should ideally not happen for positive inputs
    throw new Error('Hypotenuse is zero but sides are not.');
  }

  if (hypotenuse === Infinity || hypotenuse === -Infinity) {
    throw new Error('Hypotenuse calculation resulted in infinity.');
  }

  return hypotenuse;
}

