  if (typeof cardNumber !== 'string' || cardNumber.length === 0) {
    return false;
  }

  let sum = 0;
  let isSecondDigit = false;
  const digits = cardNumber.split('').map(Number);

  for (let i = digits.length - 1; i >= 0; i--) {
    let digit = digits[i];

    if (isSecondDigit === true) {
      digit *= 2;
      if (digit > 9) {
        digit = digit - 9;
      }
    }
    sum += digit;
    isSecondDigit = !isSecondDigit; 
  }

  return sum % 10 === 0;
};

