const findAllDivisors = (n) => {
  const divisors = [];
  if (n <= 0 || !Number.isInteger(n)) {
    return []; 
  }

  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) {
      divisors.push(i);
      if (i * i !== n) { 
        divisors.push(n / i);
      }
    }
  }

  divisors.sort((a, b) => {
    if (a < b) {
      return -1;
    } else if (a > b) {
      return 1;
    }
    return 0;
  });

  return divisors;
};

