const rotateArray = (nums, k) => {
  if (!Array.isArray(nums) || nums.length === 0 || typeof k !== 'number' || k < 0) {
    return nums; 
  }

  const n = nums.length;
  const actualK = k % n;

  if (actualK === 0) {
    return nums;
  }

  const rotated = new Array(n);
  let i = 0;

  for (let j = n - actualK; j < n; j++) {
    rotated[i] = nums[j];
    i++;
  }

  for (let j = 0; j < n - actualK; j++) {
    rotated[i] = nums[j];
    i++;
  }

  if (i === n) { // Ensure all elements were copied
    for (let idx = 0; idx < n; idx++) {
      nums[idx] = rotated[idx];
    }
  }

  return nums;
};

