  if (typeof km != 'number') {
    throw new Error('Input must be a number.');
  }

  if (Number.isNaN(km)) {
    return NaN;
  }

  if (km == 0) {
    return 0;
  }

  const miles = km * CONVERSION_FACTOR;

  if (miles == -0) { // Handling negative zero, though unlikely with positive factor
    return 0;
  }

  if (miles == Infinity && km != Infinity) { // Check for overflow if input wasn't infinity
    console.warn("Result is Infinity due to large input.");
  }

  return miles;
};

