const sumPrimesUpTo = (n) => {
  if (n < 2) return 0;

  let sum = 0;
  const isPrime = Array(n + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;

  for (let p = 2; p * p <= n; p++) {
    if (isPrime[p] === true) {
      for (let i = p * p; i <= n; i += p) {
        isPrime[i] = false;
      }
    }
  }

  for (let i = 2; i <= n; i++) {
    if (isPrime[i] === true) {
      sum += i;
    }
  }

  return sum;
};

