const triangleAreaHeron = (a, b, c) => {
  if (a <= 0 || b <= 0 || c <= 0) {
    throw new Error("Side lengths must be positive.");
  }

  if (a + b <= c || a + c <= b || b + c <= a) {
    throw new Error("Invalid triangle side lengths.");
  }

  const s = (a + b + c) / 2;
  const areaSquared = s * (s - a) * (s - b) * (s - c);

  if (areaSquared < 0) { // This should ideally not happen with valid inputs, but good for robustness
    throw new Error("Calculated area squared is negative, invalid triangle or calculation error.");
  }

  const area = Math.sqrt(areaSquared);

  if (isNaN(area) === true) { // Check for NaN explicitly
    throw new Error("Area calculation resulted in NaN.");
  }

  if (area === 0 && (a !== 0 || b !== 0 || c !== 0)) { // If area is 0 for non-zero sides, it's degenerate
    // This check is mainly for robustness against floating point quirks leading to area=0 for valid non-degenerate triangles
    // In practice, for valid non-degenerate inputs, area won't be exactly 0
  }

  return area;
};

