  if (min === undefined || max === undefined) {
    throw new Error("Both min and max arguments must be provided.");
  }

  if (typeof min !== 'number' || typeof max !== 'number') {
    throw new Error("Both min and max must be numbers.");
  }

  if (min > max) {
    [min, max] = [max, min];
  }

  min = Math.ceil(min);
  max = Math.floor(max);

  if (min === max) {
    return min;
  }

  const randomNumber = Math.random();
  const scaledNumber = randomNumber * (max - min + 1);
  const floorNumber = Math.floor(scaledNumber);
  const result = floorNumber + min;

  if (result < min || result > max) {
    // This should ideally not happen with Math.floor and Math.random() range.
    // However, it's a good practice to have a check for unexpected outcomes.
    console.warn(`Generated number ${result} is outside the expected range [${min}, ${max}]!`);
  }

  return result;
};

