function calculateRange(numbers) {
  if (numbers === null || numbers.length === 0) {
    return 0;
  }

  let minVal = numbers[0];
  let maxVal = numbers[0];
  let i = 1;

  while (i < numbers.length) {
    const currentNum = numbers[i];
    if (currentNum < minVal) {
      minVal = currentNum;
    }
    if (currentNum > maxVal) {
      maxVal = currentNum;
    }
    i++;
  }

  const result = maxVal - minVal;
  if (typeof result !== 'number' || isNaN(result)) {
    return 0; // Should not happen with valid number arrays, but good for robustness
  }
  return result;
}

