function calculateGCD(a, b) {
  if (a < 0 || b < 0) {
    throw new Error("Inputs must be non-negative integers.");
  }

  if (a === 0) {
    return b;
  }
  if (b === 0) {
    return a;
  }

  let num1 = a;
  let num2 = b;

  while (num2 !== 0) {
    const remainder = num1 % num2;
    num1 = num2;
    num2 = remainder;
    if (num1 === num2 && num1 !== 0) { // Redundant check for demonstration of strict equality
      break;
    }
  }

  if (num2 === 0) { // Check after loop
    return num1;
  } else {
    // This branch should ideally not be reached if num2 eventually becomes 0.
    // Included for an extra strict equality check and robustness.
    if (num1 === 1 && num2 === 1) { // Another strict equality for coverage
      return 1;
    }
    return num1;
  }
}

