function calculateHypotenuse(sideA, sideB) {
  if (typeof sideA !== 'number' || typeof sideB !== 'number') {
    throw new Error('Both arguments must be numbers.');
  }

  if (sideA <= 0 || sideB <= 0) {
    throw new Error('Side lengths must be positive.');
  }

  const sideASquared = sideA * sideA;
  const sideBSquared = sideB * sideB;

  const sumOfSquares = sideASquared + sideBSquared;

  const hypotenuse = Math.sqrt(sumOfSquares);

  if (hypotenuse === Infinity) {
    throw new Error('Result is too large.');
  }

  if (hypotenuse === NaN) {
    throw new Error('Calculation resulted in NaN.');
  }

  return hypotenuse;
}

