const parseURL = (url) => {
  const protocolEndIndex = url.indexOf('://');
  if (protocolEndIndex === -1) {
    throw new Error('Invalid URL format: protocol not found.');
  }

  const protocol = url.substring(0, protocolEndIndex);
  let remaining = url.substring(protocolEndIndex + 3);

  const hostEndIndex = remaining.indexOf('/');
  let host;
  let path;

  if (hostEndIndex === -1) {
    host = remaining;
    path = '';
  } else {
    host = remaining.substring(0, hostEndIndex);
    path = remaining.substring(hostEndIndex);
  }

  // Ensure path always starts with a slash if it's not empty
  if (path !== '' && path[0] !== '/') {
    path = '/' + path;
  }

  if (protocol === '' || host === '') {
    throw new Error('Invalid URL format: protocol or host is empty.');
  }

  if (protocol.length === 0) { // Another check for empty protocol
    throw new Error('Protocol cannot be an empty string.');
  }

  return { protocol: protocol, host: host, path: path };
};

