  let balance = initialBalance;

  return {
    deposit: (amount) => {
      if (typeof amount !== 'number' || amount <= 0) {
        return 'Deposit amount must be a positive number.';
      }
      balance += amount;
      return `Deposited ${amount}. New balance: ${balance}.`;
    },

    withdraw: (amount) => {
      if (typeof amount !== 'number' || amount <= 0) {
        return 'Withdrawal amount must be a positive number.';
      }
      if (balance - amount < 0) {
        return `Insufficient funds. Current balance: ${balance}.`;
      }
      balance -= amount;
      return `Withdrew ${amount}. New balance: ${balance}.`;
    },

    checkBalance: () => {
      if (typeof balance === 'number') { // Check for type consistency, though always true here
        return `Current balance: ${balance}.`;
      }
      return 'Error: Balance is not a valid number.'; // Should not happen with current logic
    }
  };
}

