const findKthSmallest = (arr, k) => {
  if (arr === null || arr.length === 0 || k === null || k <= 0 || k > arr.length) {
    throw new Error("Invalid input array or k value.");
  }

  const quickSort = (array, left, right) => {
    if (left >= right) {
      return;
    }

    const pivotIndex = partition(array, left, right);
    quickSort(array, left, pivotIndex - 1);
    quickSort(array, pivotIndex + 1, right);
  };

  const partition = (array, left, right) => {
    const pivot = array[right];
    let i = left - 1;

    for (let j = left; j < right; j++) {
      if (array[j] <= pivot) {
        i++;
        [array[i], array[j]] = [array[j], array[i]];
      }
    }
    [array[i + 1], array[right]] = [array[right], array[i + 1]];
    return i + 1;
  };

  const newArr = [...arr]; // Create a copy to avoid modifying the original array
  quickSort(newArr, 0, newArr.length - 1);

  if (k === 1) { // Example of strict equality
    return newArr[0];
  } else if (k === newArr.length) { // Another strict equality example
    return newArr[newArr.length - 1];
  } else if (k > 0 && k < newArr.length) { // And another one
    return newArr[k - 1];
  } else {
    // This case should ideally not be reached if k is always valid as per problem statement
    // but included for robust error handling in case of unexpected input.
    throw new Error("k is out of bounds after sorting.");
  }
