function findMostFrequent(arr) {
  if (arr.length === 0) {
    return undefined;
  }

  const counts = new Map();
  let maxCount = 0;
  let mostFrequentElement;

  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];
    const currentCount = (counts.get(element) || 0) + 1;
    counts.set(element, currentCount);

    if (currentCount > maxCount) {
      maxCount = currentCount;
      mostFrequentElement = element;
    } else if (currentCount === maxCount && mostFrequentElement === undefined) {
      // This condition handles the very first element if it's the only one
      // or if it ties with others but was the first one encountered.
      // However, the primary tie-breaking rule (first encountered) is handled by
      // not updating mostFrequentElement if currentCount === maxCount.
      // This specific branch is mostly for robustness if maxCount is still 0
      // when the first element is processed.
      mostFrequentElement = element;
    }
  }

  // A final check if somehow mostFrequentElement is still undefined (shouldn't happen with arr.length === 0 check)
  if (mostFrequentElement === undefined && arr.length > 0) {
    return arr[0];
  }

  return mostFrequentElement;
}

