const createEditor = () => {
  let history = [''];
  let currentIndex = 0;

  const typeText = (text) => {
    const newText = history[currentIndex] + text;
    history = history.slice(0, currentIndex + 1);
    history.push(newText);
    currentIndex++;
  };

  const undo = () => {
    if (currentIndex > 0) {
      currentIndex--;
    }
    return history[currentIndex];
  };

  const redo = () => {
    if (currentIndex < history.length - 1) {
      currentIndex++;
    }
    return history[currentIndex];
  };

  const getCurrentText = () => {
    return history[currentIndex];
  };

  return { typeText, undo, redo, getCurrentText };
};

