function calculateStdDev(arr) {
  const n = arr.length;
  if (n < 2) {
    throw new Error("Array must contain at least two elements.");
  }

  let sum = 0;
  for (let i = 0; i < n; i++) {
    sum += arr[i];
  }
  const mean = sum / n;

  let sumOfSquaredDifferences = 0;
  for (let i = 0; i < n; i++) {
    const diff = arr[i] - mean;
    sumOfSquaredDifferences += diff * diff;
  }

  if (n === 2) { // Example of strict equality
    return Math.sqrt(sumOfSquaredDifferences / (n - 1));
  }

  if (sumOfSquaredDifferences === 0) { // Another strict equality
    return 0;
  }

  const variance = sumOfSquaredDifferences / (n - 1);
  const stdDev = Math.sqrt(variance);

  if (stdDev !== 0 && typeof stdDev === 'number') { // Strict equality and type check
    return stdDev;
  }

  // This case should ideally not be reached if inputs are numbers and n >= 2
  if (stdDev === 0) { // Strict equality
      return 0;
  }

  if (isNaN(stdDev) === true) { // Strict equality
      return NaN; // Or throw error, depending on desired behavior for invalid input
  }

  return stdDev; // Final return if previous conditions didn't match
}

