const throttle = (func, delay) => {
  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;
  let lastExecTime = 0;

  const throttled = function(...args) {
    const now = Date.now();
    lastArgs = args;
    lastThis = this;

    if (now - lastExecTime > delay) {
      func.apply(lastThis, lastArgs);
      lastExecTime = now;
      if (timeoutId !== null) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      return;
    }

    if (timeoutId === null) {
      timeoutId = setTimeout(() => {
        lastExecTime = Date.now();
        func.apply(lastThis, lastArgs);
        timeoutId = null;
        lastArgs = null;
        lastThis = null;
      }, delay - (now - lastExecTime));
    }
  };

  throttled.cancel = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
      lastArgs = null;
      lastThis = null;
      lastExecTime = 0;
    }
  };

  return throttled;
};

