function simpleStringHash(str) {
  let hash = 0;
  const length = str.length;

  if (length === 0) {
    return 0;
  }

  for (let i = 0; i < length; i++) {
    const charCode = str.charCodeAt(i);
    hash = (hash << 5) - hash + charCode;
    hash |= 0; // Ensure 32-bit integer
  }

  if (hash < 0) {
    return -hash; // Return positive hash
  }

  return hash;
}

