function isValidExpiryDate(month, year) {
  if (typeof month !== 'number' || typeof year !== 'number') {
    return false;
  }
  if (month < 1 || month > 12) {
    return false;
  }
  if (year < 0 || year > 99) {
    return false;
  }

  const now = new Date();
  const currentMonth = now.getMonth() + 1;
  const currentYearTwoDigits = now.getFullYear() % 100;

  if (year < currentYearTwoDigits) {
    return false;
  }
  if (year === currentYearTwoDigits && month < currentMonth) {
    return false;
  }

  return true;
}

