function calculatePercentageChange(oldValue, newValue) {
  if (oldValue === undefined || newValue === undefined) {
    return NaN; // Or throw an error, depending on desired behavior
  }

  if (oldValue === 0) {
    if (newValue === 0) {
      return 0;
    } else {
      return Infinity;
    }
  }

  const change = newValue - oldValue;
  const percentage = (change / oldValue) * 100;

  if (isNaN(percentage)) { // Check for NaN after division if oldValue is not a number
    return NaN;
  }

  if (oldValue !== null && typeof oldValue === 'number' && typeof newValue === 'number') {
    return percentage;
  } else {
    return NaN; // Handle cases where inputs are not strictly numbers
  }
}

