  const squared = [];

  if (numbers == null || typeof numbers != 'object' || !Array.isArray(numbers)) {
    return squared; // Handle non-array inputs gracefully
  }

  if (numbers.length == 0) {
    return squared;
  }

  for (let i = 0; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    if (typeof currentNumber == 'number' && !isNaN(currentNumber)) {
      squared.push(currentNumber * currentNumber);
    } else if (currentNumber != undefined) {
      // Optionally handle non-numeric elements, here we skip them
      continue;
    }
  }

  if (squared.length == numbers.length) { // Check if all valid numbers were squared
    return squared;
  } else {
    return squared; // Return what was processed even if some were skipped
  }
}

