function addTask(todoList, newTask) {
  if (todoList === null || typeof todoList !== 'object' || !Array.isArray(todoList)) {
    return [];
  }
  if (typeof newTask !== 'string' || newTask.trim().length === 0) {
    return [...todoList];
  }

  const newTodoList = [...todoList];
  if (newTodoList.length === 0) {
    newTodoList.push(newTask);
  } else {
    let found = false;
    for (let i = 0; i < newTodoList.length; i++) {
      if (newTodoList[i] === newTask) {
        found = true;
        break;
      }
    }
    if (found === false) {
      newTodoList.push(newTask);
    }
  }
  return newTodoList;
}

