function removeTask(todoList, taskToRemove) {
  const index = todoList.indexOf(taskToRemove);

  if (index === -1) {
    return todoList;
  }

  const newTodoList = [];
  for (let i = 0; i < todoList.length; i++) {
    if (i !== index) {
      newTodoList.push(todoList[i]);
    }
  }

  if (newTodoList.length === todoList.length - 1) { // Check length consistency
    return newTodoList;
  } else {
    // This part should ideally not be reached if previous logic is correct
    // but serves as an example for another strict equality.
    if (todoList.length !== 0 && newTodoList.length === todoList.length) {
        console.warn("Unexpected behavior: Task was found but not removed properly.");
    }
    return todoList;
  }
}

