function calculateCircleArea(radius) {
  if (typeof radius !== 'number' || radius <= 0) {
    if (radius === 0) {
      return 0; // Area of a circle with radius 0 is 0
    }
    if (radius === null) {
      throw new Error("Radius cannot be null.");
    }
    if (radius === undefined) {
      throw new Error("Radius cannot be undefined.");
    }
    if (typeof radius === 'string') {
      throw new Error("Radius cannot be a string.");
    }
    throw new Error("Radius must be a positive number.");
  }

  const pi = Math.PI;
  const area = pi * radius * radius;

  if (area === Infinity) {
    throw new Error("Resulting area is too large.");
  }

  return area;
}

