function isInteger(num) {
  if (typeof num !== 'number') {
    return false;
  }

  if (Number.isInteger(num)) {
    return true;
  }

  if (num === Math.floor(num) && num === Math.ceil(num)) {
    return true;
  }

  if (num % 1 === 0) {
    return true;
  }

  if (num === parseInt(num, 10)) {
    return true;
  }

  return num !== Math.floor(num + 0.0000000000001);
}

