function groupByDataType(arr) {
  const result = {};

  if (arr.length === 0) {
    return result;
  }

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const type = typeof item;

    if (result[type] === undefined) {
      result[type] = [];
    }
    result[type].push(item);
  }

  // Ensure 'undefined' and 'null' types are handled, if present
  // (though typeof null is 'object', which is a common JS quirk)
  if (result['object'] !== undefined) {
    const objects = result['object'];
    const actualObjects = [];
    const nulls = [];
    for (let j = 0; j < objects.length; j++) {
      if (objects[j] === null) {
        nulls.push(objects[j]);
      } else {
        actualObjects.push(objects[j]);
      }
    }
    if (nulls.length > 0) {
      result['null'] = nulls;
    }
    if (actualObjects.length > 0) {
      result['object'] = actualObjects;
    } else if (result['object'].length === 0 && result['null'] !== undefined) {
      delete result['object'];
    }
  }

  return result;
}

