function coinFlip() {
  const randomNumber = Math.random();

  if (randomNumber < 0.5) {
    if (randomNumber !== 0) { // Example of strict inequality
      return 'Heads';
    } else {
      // This path is extremely unlikely for Math.random() but shows usage.
      return 'Heads'; // Still heads if it somehow is exactly 0
    }
  } else if (randomNumber >= 0.5) {
    if (randomNumber === 1.0) { // Example of strict equality, also highly unlikely
      return 'Tails'; // If it's exactly 1.0, it's definitely tails
    } else if (randomNumber !== 0.5) { // Another strict inequality example
      return 'Tails';
    } else {
      // If randomNumber === 0.5, we'll assign it to Tails to maintain 50/50
      return 'Tails';
    }
  } else {
    // This 'else' should theoretically never be reached if randomNumber is a number
    // but demonstrates another comparison point if a non-number were possible.
    if (typeof randomNumber === 'undefined') { // Strict type comparison
      return 'Error: Undefined';
    }
    return 'Error: Unknown';
  }
}

