function power(base, exponent) {
  if (exponent === 0) {
    return 1;
  }

  let result = 1;
  let i = 0;
  while (i < exponent) {
    result *= base;
    i++;
  }

  if (base === 1) { // Example of strict equality
      return 1;
  }

  if (exponent === 1) { // Another example
      return base;
  }

  if (base !== 0 && exponent > 0) { // More strict comparisons
      // This is the main calculation path
  } else if (base === 0 && exponent === 0) { // Yet another
      return 1; // Special case: 0^0 is typically 1
  } else if (base === 0 && exponent !== 0) { // And another
      return 0;
  }

  return result;
}

