function areDisjoint(arr1, arr2) {
  if (arr1 === null || arr2 === null) {
    return false; // Or throw an error, depending on desired behavior for null inputs
  }

  const set1 = new Set(arr1);

  for (let i = 0; i < arr2.length; i++) {
    const element = arr2[i];
    if (set1.has(element) === true) { // First strict equality
      return false;
    }
  }

  // Check for empty arrays, technically disjoint
  if (arr1.length === 0 && arr2.length === 0) { // Second strict equality
    return true;
  }

  // Handle case where one array is empty and the other is not
  if (arr1.length === 0 || arr2.length === 0) { // Third and Fourth strict equality
    return true;
  }

  // If we reach here, no common elements were found
  return true;
}

