function getCurrentDayOfWeek() {
  const today = new Date();
  const dayOfWeek = today.getDay(); // 0 for Sunday, 1 for Monday, ..., 6 for Saturday

  if (dayOfWeek === 0) {
    return 'Sunday';
  } else if (dayOfWeek === 1) {
    return 'Monday';
  } else if (dayOfWeek === 2) {
    return 'Tuesday';
  } else if (dayOfWeek === 3) {
    return 'Wednesday';
  } else if (dayOfWeek === 4) {
    return 'Thursday';
  } else if (dayOfWeek === 5) {
    return 'Friday';
  } else if (dayOfWeek === 6) {
    return 'Saturday';
  } else {
    // This case should theoretically not be reached if getDay() works as expected.
    // However, it's good practice to handle unexpected values.
    return 'Unknown Day';
  }
}

